/**
 * seed_real.js
 * ============
 * Seeds the on-chain RecordRegistry with REAL SHA-256 hashes computed from
 * actual PDF files in data/sample_certs/.
 *
 * Hashes were generated by: python scripts/generate_sample_certs.py
 *
 * Usage:
 *   npx hardhat run scripts/seed_real.js --network localhost
 */

const { ethers } = require("hardhat");
const fs = require("fs");
const path = require("path");

async function main() {
  const [deployer] = await ethers.getSigners();
  console.log("Seeding REAL certificate records with account:", deployer.address);

  // Load deployed contract address
  const deployFile = path.join(__dirname, "..", "deployments", "localhost.json");
  let contractAddress;
  if (fs.existsSync(deployFile)) {
    const info = JSON.parse(fs.readFileSync(deployFile, "utf-8"));
    contractAddress = info.contractAddress;
  }

  // Fallback: deploy fresh if no contract found
  let code = "0x";
  if (contractAddress) {
    code = await ethers.provider.getCode(contractAddress);
  }

  if (!contractAddress || code === "0x") {
    console.log("No deployed contract found — deploying fresh RecordRegistry...");
    const RecordRegistry = await ethers.getContractFactory("RecordRegistry");
    const registry = await RecordRegistry.deploy();
    await registry.waitForDeployment();
    contractAddress = await registry.getAddress();
    console.log("Deployed to:", contractAddress);
  }

  const registry = await ethers.getContractAt("RecordRegistry", contractAddress);
  console.log("Using RecordRegistry at:", contractAddress);

  /**
   * Real SHA-256 hashes — computed server-side from data/sample_certs/*.pdf
   * Regenerate with: python scripts/generate_sample_certs.py
   *
   * CERT-101: sample_cert_101.pdf          (Degree, active  → TC-01 MATCH)
   * CERT-102: sample_cert_102.pdf          (Transcript, active)
   * CERT-103: sample_cert_103.pdf          (Degree, then revoked → TC-04 REVOKED)
   * CERT-104: none (hash placeholder kept for query tests → TC-07 NOT_FOUND expected)
   */
  const fixtures = [
    {
      id: "CERT-101",
      hash: "0xfcf460920e9c3b897853c6b0ae0d913794738a6bce439666675de621b4f5fb28",
      docType: 1, // Degree
      revoke: false,
    },
    {
      id: "CERT-102",
      hash: "0x314160001a357c6acd9270d1ede85c5449f0c5a7efd61d0fead0320324e51740",
      docType: 2, // Transcript
      revoke: false,
    },
    {
      id: "CERT-103",
      hash: "0x853a49b14fe80f86b5401f8570cafcd094e4399dd63e1a4c5cf2cc8c2861353e",
      docType: 1, // Degree
      revoke: true,
      reasonCode: 1, // issued_in_error
    },
    {
      id: "CERT-104",
      // Placeholder hash for query/NLP tests (no corresponding sample PDF)
      hash: "0x9f2c41ab7d03e6c158b9a0fe2c47d1e3a6b80c951e7f3d42c08a5b17e92d64f0",
      docType: 1,
      revoke: false,
    },
  ];

  for (const f of fixtures) {
    // Check if record already exists
    let alreadyExists = false;
    try {
      const [exists] = await registry.isRevoked(f.id);
      alreadyExists = exists;
    } catch (_) {
      alreadyExists = false;
    }

    if (!alreadyExists) {
      console.log(`Registering ${f.id} with hash ${f.hash.slice(0, 18)}...`);
      const tx = await registry.registerRecord(f.id, f.hash, f.docType);
      await tx.wait();
      console.log(`  ✓ Registered ${f.id} (tx: ${tx.hash})`);

      if (f.revoke) {
        console.log(`  Revoking ${f.id} with reason ${f.reasonCode}...`);
        const revTx = await registry.revokeRecord(f.id, f.reasonCode);
        await revTx.wait();
        console.log(`  ✓ Revoked ${f.id} (tx: ${revTx.hash})`);
      }
    } else {
      console.log(`  ↷ Skipping ${f.id} (already registered)`);
    }
  }

  console.log("\nSeeding complete! Real PDF certificates registered on-chain.");
  console.log("Test with: data/sample_certs/sample_cert_101.pdf → CERT-101 → MATCH");
  console.log("           data/sample_certs/sample_cert_101_tampered.pdf → CERT-101 → MISMATCH");
}

if (require.main === module) {
  main()
    .then(() => process.exit(0))
    .catch((error) => {
      console.error("Seeding failed:", error);
      process.exit(1);
    });
}

module.exports = { main };

